const api = async <T,>(path: string, init?: RequestInit): Promise<T> => {
  const response = await fetch(`/api/v1${path}`, { ...init, headers: { Accept: 'application/json', ...init?.headers } });
  if (!response.ok) throw new Error((await response.json().catch(() => ({})) as { detail?: string }).detail || `Request failed (${response.status})`);
  return response.json() as Promise<T>;
};
type Session = { remote: boolean; localUpstream: boolean; isAdmin: boolean; localAdmin: boolean; username: string; profile?: string; unavailable?: boolean };
const thumb = (video: Partial<Video & Playlist>) => videoThumbnailUrl(video);
function Thumbnail({ image, fallback = '', eager = false }: { image: string; fallback?: string; eager?: boolean }) { const [failures, setFailures] = useState(0); const source = thumbnailImageSource(image, fallback, failures); const presentation = thumbnailPresentation(source); return presentation.image ? <img loading={thumbnailLoading(eager)} src={presentation.image} alt="" onError={() => setFailures(count => count + 1)} /> : <span className="thumbnail-fallback" role="img" aria-label={presentation.label}><span aria-hidden="true">▧</span><small>{presentation.label}</small></span>; }
const duration = (n?: number) => n ? `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')}` : '';
const nfmt = (n?: number) => n == null ? '' : new Intl.NumberFormat().format(n);
const ShareDialogContext = createContext<(video: Video) => void>(() => undefined);
const shareChannel = async (channel: Channel, notify: (message: string | null) => void) => {
  const url = channelShareUrl(channel);
  if (!url) return notify('The upstream source link is unavailable for this channel.');
  try {
    if (navigator.share) await navigator.share({ title: channel.author, url });
    else if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(url);
    else { const field = document.createElement('textarea'); field.value = url; field.style.position = 'fixed'; field.style.opacity = '0'; document.body.append(field); field.select(); if (!document.execCommand('copy')) throw new Error('Clipboard unavailable'); field.remove(); }
    notify('Upstream channel link ready to share.');
  } catch (error) { if ((error as Error).name !== 'AbortError') notify('Unable to share this link.'); }
};

const downloadVideo = async (video: Video, notify: (message: string | null) => void) => {
  try {
    const detail = await api<{ formatStreams?: { itag: string; url: string; type?: string; container?: string }[] }>(`/videos/${encodeURIComponent(video.videoId)}?proxy=true&proxy_mode=relay`);
    const source = chooseDownloadSource(detail);
    if (!source) return notify('No downloadable MP4 stream is available for this video.');
    const anchor = document.createElement('a');
    anchor.href = downloadUrl(source, video.title);
    anchor.download = '';
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
  } catch { notify('Unable to prepare an MP4 download for this video.'); }
};

function VideoMenu({ video, notify, markWatched, addToPlaylist }: { video: Video; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void }) { const [mark, playlist, download] = videoMenuActions(); return <details className="more-menu"><summary aria-label={`More actions for ${video.title}`}>⋯</summary><div><button type="button" onClick={() => markWatched(video)}>{mark}</button><button type="button" onClick={() => addToPlaylist(video)}>{playlist}</button><button type="button" onClick={() => downloadVideo(video, notify)}>{download}</button></div></details>; }
function VideoActions({ video, saved, save, notify, markWatched, addToPlaylist, more = true }: { video: Video; saved: boolean; save: (video: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void; more?: boolean }) { const openShare = useContext(ShareDialogContext); return <div className="actions has-more"><button className="secondary" onClick={() => save(video)}>{saveButtonLabel(saved)}</button><button className="secondary" type="button" onClick={() => openShare(video)}>Share</button>{!more && <button className="secondary" type="button" onClick={() => markWatched(video)}>Mark as watched</button>}{more && <VideoMenu video={video} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} />}</div>; }

function PlaylistPicker({ video, playlists, selectPlaylist, addNew, close }: { video: Video; playlists: Store['playlists']; selectPlaylist: (id: string) => void; addNew: () => void; close: () => void }) {
  return <div className="playlist-picker-backdrop" role="presentation" onMouseDown={close}><section className="dialog playlist-picker" role="dialog" aria-modal="true" aria-labelledby="playlist-picker-title" onMouseDown={event => event.stopPropagation()}><div className="heading"><h2 id="playlist-picker-title">Add to playlist</h2><button className="secondary" type="button" aria-label="Close playlist picker" onClick={close}>Close</button></div><p className="subtle">Choose a playlist for “{video.title}”.</p>{playlists.length ? <div className="playlist-picker-list">{playlists.map(playlist => <button className="secondary" type="button" key={playlist.id} onClick={() => selectPlaylist(playlist.id)}>{playlist.name}<small>{Array.isArray(playlist.videos) ? playlist.videos.length : 0} videos</small></button>)}</div> : <p className="empty">No playlists yet. Create one to add this video.</p>}<button className="primary" type="button" onClick={addNew}>Add new</button></section></div>;
}

function ShareDialog({ video, close, notify }: { video: Video; close: () => void; notify: (message: string | null) => void }) {
  const url = shareDialogUrl(video);
  const input = useRef<HTMLInputElement>(null);
  const [copied, setCopied] = useState(false);
  useEffect(() => { input.current?.select(); }, []);
  if (!url) return null;
  const copy = async () => { try { if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(url); else { input.current?.select(); if (!document.execCommand('copy')) throw new Error('Clipboard unavailable'); } setCopied(true); } catch { notify('Unable to copy this link.'); } };
  const share = async () => { const availability = nativeShareAvailability(window.isSecureContext, typeof navigator.share === 'function'); if (availability === 'insecure') return notify('System sharing requires an HTTPS connection. Open Yattee Web over HTTPS, then try Share again.'); if (availability === 'unsupported') return notify('System sharing is unavailable in this browser.'); try { await navigator.share!({ title: video.title, url }); } catch (error) { if ((error as Error).name !== 'AbortError') notify('Unable to share this link.'); } };
  return <div className="share-dialog-backdrop" role="presentation" onMouseDown={close}><section className="dialog share-dialog" role="dialog" aria-modal="true" aria-labelledby="share-dialog-title" onMouseDown={event => event.stopPropagation()}><div className="heading"><h2 id="share-dialog-title">Share video</h2><button className="secondary" type="button" onClick={close}>Close</button></div><label className="subtle" htmlFor="share-link">YouTube link</label><div className="share-link-controls"><input id="share-link" ref={input} value={url} readOnly onFocus={event => event.currentTarget.select()} aria-label="YouTube link" /><button className="secondary" type="button" onClick={() => void copy()}>{shareDialogCopyLabel(copied)}</button><button className="primary" type="button" onClick={() => void share()}>Share</button></div></section></div>;
}

function VideoCards({ videos, bookmarks, navigate, save, queue, notify, markWatched, addToPlaylist, eagerThumbnails = false }: { videos: (Video | Playlist | Channel)[]; bookmarks: Video[]; navigate: (route: string) => void; save: (v: Video) => void; queue: (v: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void; eagerThumbnails?: boolean }) {
  const cards = Array.isArray(videos) ? videos : [];
  return <div className="grid">{cards.map((item) => {
    if ('playlistId' in item) return <article className="card" key={item.playlistId}><button className="thumbnail" onClick={() => navigate(`playlist/${item.playlistId}`)}><Thumbnail image={thumb(item)} /><span className="badge">PLAYLIST</span></button><button className="card-title" onClick={() => navigate(`playlist/${item.playlistId}`)}>{item.title}</button><p className="meta">{item.author} · {item.videoCount || 0} videos</p></article>;
    if (!('videoId' in item)) return <article className="card" key={item.authorId}><button className="thumbnail" onClick={() => navigate(`channel/${encodeURIComponent(item.authorId)}`)}><Thumbnail image={item.authorThumbnails?.at(-1)?.url || item.authorThumbnails?.[0]?.url || ''} /><span className="badge">CHANNEL</span></button><button className="card-title" onClick={() => navigate(`channel/${encodeURIComponent(item.authorId)}`)}>{item.author}</button><p className="meta">{item.subCount ? `${nfmt(item.subCount)} subscribers` : 'Channel'}</p></article>;
    return <article className="card" key={item.videoId}><button className="thumbnail" onClick={() => navigate(`watch/${item.videoId}`)}><Thumbnail image={thumb(item)} fallback={videoThumbnailFallback(item)} eager={eagerThumbnails} /><span className="badge">{item.liveNow ? 'LIVE' : duration(item.lengthSeconds)}</span></button><button className="card-title" onClick={() => navigate(`watch/${item.videoId}`)}>{item.title}</button><button className="channel" onClick={() => navigate(`channel/${encodeURIComponent(item.authorId)}`)}>{item.author}</button><p className="meta">{item.publishedText}{item.viewCount ? ` · ${nfmt(item.viewCount)} views` : ''}</p><VideoActions video={item} saved={bookmarks.some(bookmark => bookmark.videoId === item.videoId)} save={save} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} /></article>;
  })}</div>;
}


function PlaylistVideoList({ title, subtitle, videos, bookmarks, navigate, save, queue, notify, markWatched, addToPlaylist, saveAll }: { title: string; subtitle?: string; videos: Video[]; bookmarks: Video[]; navigate: (route: string) => void; save: (video: Video) => void; queue: (video: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void; saveAll: () => void }) {
  const [query, setQuery] = useState('');
  const [pageIndex, setPageIndex] = useState(0);
  const listing = playlistVideoPage(videos, query, pageIndex);
  return <><div className="heading"><div><h1>{title}</h1>{subtitle ? <p className="subtle">{subtitle}</p> : null}</div><button className="secondary" onClick={saveAll}>Save all</button></div><div className="channels-search video-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.4" /><path d="m16 16 4.5 4.5" /></svg><input type="search" value={query} onChange={event => { setQuery(event.currentTarget.value); setPageIndex(0); }} placeholder="Search playlist" aria-label="Search playlist videos" /></div>{listing.matching.length ? <><VideoCards videos={listing.videos} bookmarks={bookmarks} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} />{listing.page.pages > 1 ? <div className="actions"><button className="secondary" disabled={listing.page.page === 0} onClick={() => setPageIndex(current => Math.max(0, current - 1))}>Previous</button><span className="subtle">Page {listing.page.page + 1} of {listing.page.pages}</span><button className="secondary" disabled={listing.page.page + 1 === listing.page.pages} onClick={() => setPageIndex(current => current + 1)}>Next</button></div> : null}</> : <p className="empty">{query ? 'No playlist videos match that search.' : 'This playlist has no videos.'}</p>}</>;
}

function ChannelsView({ channels, navigate }: { channels: Channel[]; navigate: (route: string) => void }) {
  const [query, setQuery] = useState('');
  const visible = matchingChannels(channels, query);
  return <><div className="channels-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.4" /><path d="m16 16 4.5 4.5" /></svg><input autoFocus type="search" value={query} onChange={event => setQuery(event.currentTarget.value)} placeholder="Search channels" aria-label="Search channels" /></div>{visible.length ? <div className="channels-grid">{visible.map(channel => { const avatar = channelAvatar(channel); return <button className="channel-card" key={channel.authorId} onClick={() => navigate(`channel/${encodeURIComponent(channel.authorId)}`)}><span className="channel-avatar">{avatar.image ? <img src={avatar.image} alt="" /> : <span>{avatar.initial}</span>}</span><strong>{channel.author}</strong>{channel.subCount ? <small>{nfmt(channel.subCount)} subscribers</small> : null}</button>; })}</div> : <p className="empty">{query ? 'No subscribed channels match that search.' : 'Subscribe from a channel page or import Google Takeout subscriptions in Settings.'}</p>}</>;
}

class RouteErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
  state: { error: Error | null } = { error: null };
  static getDerivedStateFromError(error: Error) { return { error }; }
  render() { return this.state.error ? <section className="dialog error"><p>This view could not be rendered: {this.state.error.message}.</p><button className="primary" onClick={() => location.reload()}>Reload</button></section> : this.props.children; }
}

function AdminSetup({ complete }: { complete: () => void }) { const [password, setPassword] = useState(''); const [error, setError] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); const response = await fetch('/local-admin/setup', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }) }); if (!response.ok) return setError((await response.json()).detail || 'Unable to set the admin password'); complete(); }; return <main className="content"><section className="dialog"><h1>Set Yattee Web admin password</h1><p className="subtle">This local-only administrator is always named <strong>admin</strong>. Its password is stored only as a verifier in this container’s filesystem.</p><form onSubmit={submit}><input type="password" minLength={8} autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 8 characters" required /><button className="primary">Set admin password</button></form>{error && <p className="error">{error}</p>}</section></main>; }
function AdminRecovery({ authenticate }: { authenticate: () => Promise<void> }) { useEffect(() => { authenticate().catch(() => undefined); }, [authenticate]); return <main className="content"><section className="dialog"><h1>Admin settings</h1><p className="notice">Please provide yattee-web admin password</p></section></main>; }

function MobileNavIcon({ icon }: { icon: 'home' | 'search' | 'subscriptions' | 'channels' | 'settings' | 'more' }) { const common = { fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }; if (icon === 'home') return <svg viewBox="0 0 24 24" aria-hidden="true"><path {...common} d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1Z" /></svg>; if (icon === 'search') return <svg viewBox="0 0 24 24" aria-hidden="true"><circle {...common} cx="10.8" cy="10.8" r="6.4" /><path {...common} d="m16 16 4.5 4.5" /></svg>; if (icon === 'channels') return <svg viewBox="0 0 24 24" aria-hidden="true"><circle {...common} cx="12" cy="8" r="3.5" /><path {...common} d="M5 21a7 7 0 0 1 14 0" /></svg>; if (icon === 'more') return <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.7" fill="currentColor" /><circle cx="12" cy="12" r="1.7" fill="currentColor" /><circle cx="19" cy="12" r="1.7" fill="currentColor" /></svg>; if (icon === 'subscriptions') return <svg viewBox="0 0 24 24" aria-hidden="true"><rect {...common} x="3" y="5" width="18" height="14" rx="2" /><path {...common} d="m10 9 5 3-5 3Z" /></svg>; return <svg viewBox="0 0 24 24" aria-hidden="true"><path {...common} d="M12 8.3a3.7 3.7 0 1 0 0 7.4 3.7 3.7 0 0 0 0-7.4Zm8 3.7-2.1-.7a6.2 6.2 0 0 0-.6-1.4l1-2-2.2-2.2-2 1.1a6.2 6.2 0 0 0-1.4-.6L12 3.9 8.9 5l-.7 2.1a6.2 6.2 0 0 0-1.4.6l-2-1L2.6 8.9l1.1 2a6.2 6.2 0 0 0-.6 1.4l-2.1.7L2.1 16l2.1.7a6.2 6.2 0 0 0 .6 1.4l-1.1 2 2.2 2.2 2-1.1a6.2 6.2 0 0 0 1.4.6l.7 2.1 3.1-1.1.7-2.1a6.2 6.2 0 0 0 1.4-.6l2 1.1 2.2-2.2-1.1-2a6.2 6.2 0 0 0 .6-1.4L20 16l1.1-3.1Z" /></svg>; }

function App() {
  const [store, setStore] = useState<Store>(initialStore);
  const [stateReady, setStateReady] = useState(false);
  const [stateError, setStateError] = useState(false);
  const [stateLoadAttempt, setStateLoadAttempt] = useState(0);
  const [offlineProfile, setOfflineProfile] = useState(currentOfflineProfile);
  const [offlineMode, setOfflineMode] = useState(false);
  const [route, setRoute] = useState(initialRoute(location.hash.slice(1)));
  const [query, setQuery] = useState('');
  const [message, setMessage] = useState<string | null>(null);
  const [controls, setControls] = useState<ParentalControls>(defaultParentalControls);
  const [session, setSession] = useState<Session>({ remote: false, localUpstream: false, isAdmin: false, localAdmin: false, username: '' });
  const [localAdminConfigured, setLocalAdminConfigured] = useState<boolean | null>(null); const [adminRecovery, setAdminRecovery] = useState(false); const [remoteLoggedOut, setRemoteLoggedOut] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [controlsReady, setControlsReady] = useState(false);
  const [controlsError, setControlsError] = useState(false);
  const [playlistVideo, setPlaylistVideo] = useState<Video | null>(null);
  const [shareVideo, setShareVideo] = useState<Video | null>(null);
  const [connectionAttempt, setConnectionAttempt] = useState(0);
  useEffect(() => { fetch('/local-admin/status').then(r => r.json()).then(status => setLocalAdminConfigured(!!status.configured)).catch(() => setLocalAdminConfigured(true)); }, []);
  useEffect(() => { retryConnection(async () => { const sessionResponse = await fetch('/session'); if (!sessionResponse.ok) throw new Error('Session unavailable'); const nextSession = await sessionResponse.json(); if (nextSession.unavailable) throw new Error('Yattee Server unavailable'); if (nextSession.loggedOut) return { session: nextSession, controls: null }; const response = await fetch('/controls'); if (!response.ok) throw new Error('Parental controls unavailable'); return { session: nextSession, controls: await response.json() }; }).then(result => { const nextSession = { localAdmin: false, ...result.session }; setSession(nextSession); const profile = nextSession.profile || 'local'; rememberOfflineProfile(profile); setOfflineProfile(profile); if (result.session.loggedOut) { setRemoteLoggedOut(true); } else { setControls({ ...defaultParentalControls, ...(result.controls?.controls || {}) }); } setControlsReady(true); }).catch(() => { setSession({ remote: true, localUpstream: false, isAdmin: false, localAdmin: false, username: '', profile: offlineProfile, unavailable: true }); setControlsReady(true); }); }, [connectionAttempt]);
  useEffect(() => { let active = true; setStateReady(false); loadStateWithOfflineFallback(loadSyncedState, browserOfflineProfileStore(offlineProfile)).then(result => { if (!active) return; setStore(result.state); if (result.controls) setControls(result.controls); setOfflineMode(result.offline); setStateError(false); setStateReady(true); }).catch(() => { if (!active) return; setStateError(true); setStateReady(true); }); return () => { active = false; }; }, [stateLoadAttempt, offlineProfile]);
  useEffect(() => { if (stateReady && controlsReady && !stateError && !adminRecovery) void saveOfflineProfile(browserOfflineProfileStore(offlineProfile), store, controls, offlineMode).catch(() => undefined); }, [store, controls, stateReady, controlsReady, stateError, adminRecovery, offlineProfile, offlineMode]);
  useEffect(() => { if (stateReady && !stateError && !session.unavailable && !adminRecovery && !offlineMode) saveSyncedState(store).catch(() => setOfflineMode(true)); }, [store, stateReady, stateError, session.unavailable, adminRecovery, offlineMode]);
  const synchronizeOfflineProfile = useCallback(async () => { if (!offlineMode || !stateReady || stateError || adminRecovery) return; try { await saveSyncedState(store); await saveOfflineProfile(browserOfflineProfileStore(offlineProfile), store, controls, false); setOfflineMode(false); setConnectionAttempt(attempt => attempt + 1); } catch { /* Keep the local snapshot queued until the server returns. */ } }, [offlineMode, stateReady, stateError, adminRecovery, store, controls, offlineProfile]);
  useEffect(() => { if (!offlineMode) return; const retry = () => void synchronizeOfflineProfile(); addEventListener('online', retry); const interval = window.setInterval(retry, 10000); return () => { removeEventListener('online', retry); window.clearInterval(interval); }; }, [offlineMode, synchronizeOfflineProfile]);
  useEffect(() => { document.documentElement.dataset.theme = store.settings.theme; }, [store.settings.theme]);
  useEffect(() => { const onHash = () => setRoute(initialRoute(location.hash.slice(1))); addEventListener('hashchange', onHash); return () => removeEventListener('hashchange', onHash); }, []);
  const navigate = (next: string) => { if (blockedRoute(next, controls)) { setMessage('This section is disabled by parental controls.'); return; } location.hash = next; };
  const update = (fn: (old: Store) => Store) => setStore(old => fn(old));
  const add = (field: 'bookmarks' | 'queue', video: Video) => { if (!canAddContent(field === 'bookmarks' ? 'bookmark' : 'queue', controls)) return setMessage('Adding content is disabled by parental controls.'); update(s => s[field].some(x => x.videoId === video.videoId) ? s : { ...s, [field]: [video, ...s[field]] }); };
  const nav = ['⌂ Home|home', '◉ Feed|subscriptions', '◌ Channels|channels', '▤ Saved|queue', '◷ History|history', '☷ Playlists|playlists', '⚙ Settings|settings'].filter(x => !((controls.enabled && controls.disableSearch && x.endsWith('|search')) || (controls.enabled && controls.disablePlaylists && x.endsWith('|playlists'))));
  const save = (video: Video) => { if (!canAddContent('queue', controls)) return setMessage('Adding content is disabled by parental controls.'); update(s => ({ ...s, queue: toggleSaved(s.queue, video) })); };
  const openPlaylistPicker = (video: Video) => { if (!canAddContent('playlist', controls)) return setMessage('Adding content is disabled by parental controls.'); setPlaylistVideo(video); };
  const selectPlaylist = (playlistId: string) => { if (!playlistVideo) return; update(s => ({ ...s, playlists: addVideoToLocalPlaylist(s.playlists, playlistId, playlistVideo) })); setPlaylistVideo(null); };
  const addNewPlaylist = () => { if (!playlistVideo) return; const name = window.prompt('Playlist name')?.trim(); if (!name) return; update(s => ({ ...s, playlists: [...s.playlists, createLocalPlaylist(name, playlistVideo)] })); setPlaylistVideo(null); };
  const openShareDialog = (video: Video) => { if (!shareDialogUrl(video)) return setMessage('The upstream source link is unavailable for this video.'); setShareVideo(video); };
  const body = useMemo(() => <RouteErrorBoundary key={route}><Route route={route} store={store} update={update} navigate={navigate} save={save} queue={v => add('queue', v)} notify={setMessage} controls={controls} onControls={setControls} session={session} addToPlaylist={openPlaylistPicker} /></RouteErrorBoundary>, [route, store, controls, session]);
  const submit = (event: FormEvent) => { event.preventDefault(); const value = query.trim(); if (value) { update(s => ({ ...s, searchHistory: [value, ...s.searchHistory.filter(item => item !== value)].slice(0, 100) })); navigate(`search/${encodeURIComponent(value)}`); } };
  const switchToLocal = async () => { try { const response = await fetch('/config', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ instanceUrl: '' }) }); if (!response.ok) throw new Error(); location.reload(); } catch { setMessage('Unable to switch to local-only mode.'); } };
  const authenticateLocalAdmin = useCallback(async () => { const adminResponse = await fetch('/local-admin/session'); if (!adminResponse.ok) throw new Error('Admin authentication failed'); const controlsResponse = await fetch('/controls'); if (!controlsResponse.ok) throw new Error('Unable to load admin controls'); const saved = await controlsResponse.json(); setSession({ remote: false, localUpstream: false, isAdmin: true, localAdmin: true, username: 'admin' }); setControls({ ...defaultParentalControls, ...(saved.controls || {}) }); setControlsError(false); setStateError(false); setControlsReady(true); setStateReady(true); setAdminRecovery(true); setRoute('settings'); }, []);
  const signIn = async () => { const response = await fetch('/login', { method: 'POST' }); if (response.ok) location.reload(); };
  const refreshConnection = () => { setControlsReady(false); setRemoteLoggedOut(false); setConnectionAttempt(attempt => attempt + 1); };
  const reloadProfile = () => { setStateError(false); setControlsError(false); setStateLoadAttempt(attempt => attempt + 1); };
  const logout = async () => { const response = await fetch('/logout', { method: 'POST' }); if (response.ok) location.reload(); };
  if (localAdminConfigured === false) return <AdminSetup complete={() => setLocalAdminConfigured(true)} />;
  if (remoteLoggedOut) return <main className="content"><section className="dialog"><h1>Signed out</h1><p className="subtle">Your Yattee Web remote session is locked. Sign in to resume with this browser’s Yattee Server credentials.</p><button className="primary" onClick={signIn}>Sign in</button></section></main>;
  if ((stateError || controlsError) && !session.unavailable && !adminRecovery) return <main className="content"><p className="error"><strong>Yattee Web could not load its saved profile.</strong></p><div className="actions"><button className="primary" onClick={reloadProfile}>Reload profile</button><button className="secondary" onClick={() => setAdminRecovery(true)}>Admin settings</button></div></main>;
  if (adminRecovery && !session.localAdmin) return <AdminRecovery authenticate={authenticateLocalAdmin} />;
  if (adminRecovery && session.localAdmin) return <main className="content"><RouteErrorBoundary><Route route="settings" store={store} update={update} navigate={() => undefined} save={() => undefined} queue={() => undefined} notify={setMessage} controls={controls} onControls={setControls} session={session} addToPlaylist={openPlaylistPicker} /></RouteErrorBoundary></main>;
  if (!controlsReady || !stateReady) return <main className="content"><p className="empty">Loading Yattee data…</p></main>;
  if (session.unavailable && !offlineMode) return <main className="outage-page"><button className="secondary outage-admin" onClick={() => setAdminRecovery(true)}>Admin Login</button><section className="outage-content"><h1>Yattee Server is down</h1><p className="subtle">Cached Yattee Web content is unavailable until the connection is restored.</p><button className="primary" onClick={refreshConnection}>Retry connection</button></section></main>;
  return <ShareDialogContext.Provider value={openShareDialog}><div className={`app ${controls.enabled && controls.disablePlaylists ? 'content-additions-disabled' : ''}`}><header className="topbar"><button className="brand" onClick={() => navigate('home')}>Yattee <b>WEB</b></button>{route.split('/')[0] === 'search' && !(controls.enabled && controls.disableSearch) && <form className="search" onSubmit={submit}><input id="global-search" autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Search videos, channels, playlists" /><button>Search</button></form>}<button className="search-icon" type="button" aria-label="Search" onClick={() => navigate('search')}><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.4" /><path d="m16 16 4.5 4.5" /></svg></button><button className="secondary client-refresh" type="button" onClick={() => location.reload()}>Refresh</button></header><div className="layout"><nav className={`nav mobile-menu ${menuOpen ? 'open' : ''}`} aria-label="All settings and navigation">{profileMenuLabel(session.username) && <p className="menu-profile">{profileMenuLabel(session.username)}</p>}{nav.map(x => { const [label, path] = x.split('|'); return <button className={route === path ? 'active' : ''} onClick={() => { navigate(path); setMenuOpen(false); }} key={path}>{label.replace(/^[^ ]+ /, '')}</button>; })}{(session.remote || session.localUpstream) && <button className="menu-logout" onClick={logout}>Log out</button>}</nav><main className="content">{session.unavailable ? <p className="notice"><strong>Offline mode.</strong> Your cached profile is available locally. Playback and online browsing are disabled; saved changes will sync automatically when Yattee Web reconnects. <button className="secondary" onClick={refreshConnection}>Retry connection</button></p> : null}{message && <p className="notice notice-overlay" role="alert">{message}<button className="secondary" onClick={() => setMessage(null)}>Dismiss</button></p>}{body}</main></div><nav className="mobile-bottom-nav" aria-label="Primary navigation">{mobileNavigation.map(item => <button key={item.route} className={(item.route === 'menu' ? menuOpen : route.split('/')[0] === item.route) ? 'active' : ''} onClick={() => item.route === 'menu' ? setMenuOpen(open => !open) : (navigate(item.route), setMenuOpen(false))}><MobileNavIcon icon={item.route === 'menu' ? 'more' : item.route as 'home' | 'search' | 'subscriptions' | 'channels'} />{item.label && <span>{item.label}</span>}</button>)}</nav>{playlistVideo && <PlaylistPicker video={playlistVideo} playlists={store.playlists} selectPlaylist={selectPlaylist} addNew={addNewPlaylist} close={() => setPlaylistVideo(null)} />}{shareVideo && <ShareDialog video={shareVideo} close={() => setShareVideo(null)} notify={setMessage} />}</div></ShareDialogContext.Provider>;
}

function Route({ route, store, update, navigate, save, queue, notify, controls, onControls, session, addToPlaylist }: { route: string; store: Store; update: (f: (s: Store) => Store) => void; navigate: (r: string) => void; save: (v: Video) => void; queue: (v: Video) => void; notify: (m: string | null) => void; controls: ParentalControls; onControls: (controls: ParentalControls) => void; session: Session; addToPlaylist: (video: Video) => void }) {
  const [data, setData] = useState<unknown>(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [filter, setFilter] = useState('video'); const [upstreamLink, setUpstreamLink] = useState(''); const [feedAttempt, setFeedAttempt] = useState(0); const [feedQuery, setFeedQuery] = useState(''); const [feedPageIndex, setFeedPageIndex] = useState(0); const [feedRefreshing, setFeedRefreshing] = useState(false); const [feedError, setFeedError] = useState('');
  const [base, id] = route.split('/', 2);
  const markVideoWatched = (video: Video) => update(state => ({ ...state, history: markHistoryWatched(state.history, video) }));

  const historyForRoute = routeUsesHistory(route) ? store.history : null;
  useEffect(() => { let active = true; let retry: number | undefined; const cachedFeed = base === 'subscriptions' && store.feedCache.videos.length ? { status: 'ready', videos: store.feedCache.videos, total: store.feedCache.videos.length } : null; setError(''); setFeedError(''); if (cachedFeed) { setData(cachedFeed); setLoading(false); setFeedRefreshing(true); } else { setLoading(true); setData(null); setFeedRefreshing(base === 'subscriptions'); } const get = async () => { if (blockedRoute(route, controls)) throw new Error('This section is disabled by parental controls.'); if (base === 'home') return continueWatching(store.history); if (base === 'search' && id) return api<(Video | Channel | Playlist)[]>(`/search?q=${encodeURIComponent(decodeURIComponent(id))}&type=${filter}`); if (base === 'watch' && id) return api<any>(`/videos/${id}?proxy=true&proxy_mode=relay`); if (base === 'watch-url' && id) return api<any>(`/extract?url=${encodeURIComponent(decodeURIComponent(id))}`); if (base === 'channel' && id) { const channel = channelFromSubscriptions(store.subscriptions, decodeURIComponent(id)) || await api<Channel>(`/channels/${decodeURIComponent(id)}`); const feed = await api<{ status: string; videos: Video[]; pending_count?: number }>('/feed', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(channelFeedRequest(channel)) }); return [channel, feed]; } if (base === 'playlist' && id) return api<Playlist>(`/playlists/${id}`); if (base === 'subscriptions') return api<{ status: string; videos: Video[]; total?: number; ready_count?: number; pending_count?: number; error_count?: number }>('/feed', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(feedRequestForSubscriptions(store.subscriptions)) }); return null; };
    get().then(x => { if (!active) return; if (base === 'subscriptions') { const result = x as { status: string; videos: Video[]; total?: number; pending_count?: number }; if (result.status === 'fetching') { if (!cachedFeed) setData(result); retry = window.setTimeout(() => setFeedAttempt(attempt => attempt + 1), 3000); return; } const feedCache = mergeFeedCache(store.feedCache, result.videos); if (feedCache !== store.feedCache) update(state => state.feedCache === store.feedCache ? { ...state, feedCache } : state); setData({ ...result, videos: feedCache.videos, total: Math.max(result.total || 0, feedCache.videos.length) }); setFeedRefreshing(false); return; } setData(x); }).catch(e => { if (!active) return; if (cachedFeed) { setFeedRefreshing(false); setFeedError('Unable to check for feed updates. Showing your saved feed.'); } else setError(e.message); }).finally(() => active && setLoading(false)); return () => { active = false; if (retry) window.clearTimeout(retry); };
  }, [route, filter, store.subscriptions, historyForRoute, controls, feedAttempt]);
  useEffect(() => { const feed = base === 'channel' ? (data as [Channel, { status?: string }] | null)?.[1] : null; if (base !== 'channel' || feed?.status !== 'fetching') return; const timer = window.setTimeout(() => setFeedAttempt(attempt => attempt + 1), 3000); return () => window.clearTimeout(timer); }, [base, data]);
  if (base === 'history') return <Library title="Watch history" videos={store.history} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} clear={() => update(s => ({ ...s, history: [] }))} />;
  if (base === 'playlists') return <Playlists store={store} update={update} navigate={navigate} />;
  if (base === 'local-playlist') { const playlist = store.playlists.find(entry => entry.id === decodeURIComponent(id || '')); if (!playlist) return <p className="empty">This local playlist was not found.</p>; return <PlaylistVideoList title={playlist.name} subtitle={`${playlist.videos.length} videos`} videos={playlist.videos} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} saveAll={() => update(state => ({ ...state, queue: [...playlist.videos, ...state.queue.filter(queued => !playlist.videos.some(video => video.videoId === queued.videoId))] }))} />; }
  if (base === 'queue') return <Queue store={store} update={update} navigate={navigate} save={save} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} />;
  if (base === 'settings') return <Settings store={store} update={update} controls={controls} onControls={onControls} session={session} />;
  if (base === 'channels') return <ChannelsView channels={store.subscriptions} navigate={navigate} />;
  if (session.unavailable && upstreamRequired(route)) return <p className="notice">This section requires Yattee Server. It will be available again when the upstream is healthy.</p>;
  if (loading) return <p className="empty">Loading Yattee…</p>; if (error) return <section className="dialog error"><p>{error === 'Authentication required' ? <>The local Yattee Server requires authentication. <button className="primary" onClick={() => location.assign('/upstream-login')}>Log in</button></> : error}</p><button className="secondary" onClick={() => location.reload()}>Reload</button></section>;
  if (base === 'home') return <><div className="heading"><div><h1>Home</h1><p className="subtle">Continue watching</p></div></div><form className="upstream-link-form" onSubmit={event => { event.preventDefault(); const target = upstreamWatchRoute(upstreamLink); if (target) navigate(target); else notify('Enter a valid http:// or https:// upstream video link.'); }}><label htmlFor="upstream-link">Stream an upstream link</label><div><input id="upstream-link" type="url" inputMode="url" value={upstreamLink} onChange={event => setUpstreamLink(event.currentTarget.value)} placeholder="Paste a YouTube, Twitch, Instagram, or other supported link" /><button className="primary">Stream</button></div></form>{(data as Video[])?.length ? <VideoCards eagerThumbnails videos={data as Video[]} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} /> : <p className="empty">Videos you start and leave unfinished will appear here.</p>}</>;
  if (base === 'search') return <><div className="heading"><h1>{id ? `Results for “${decodeURIComponent(id)}”` : 'Search'}</h1><select className="filter" value={filter} onChange={e => setFilter(e.target.value)}><option value="video">Videos</option><option value="channel">Channels</option><option value="playlist">Playlists</option><option value="all">All</option></select></div>{id ? <VideoCards videos={(data as (Video | Channel | Playlist)[]) || []} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} /> : <p className="empty">Search for creators, videos, and playlists.</p>}</>;
  if ((base === 'watch' || base === 'watch-url') && data) return <Player video={data as any} store={store} update={update} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} />;
  if (base === 'channel' && data) { const result = data as [Channel, { videos: Video[]; status?: string; pending_count?: number }]; return <ChannelPage info={result[0]} videos={result[1].videos} fetching={result[1].status === 'fetching'} store={store} update={update} navigate={navigate} save={save} queue={queue} controls={controls} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} />; }
  if (base === 'playlist' && data) { const playlist = data as Playlist; const videos = Array.isArray(playlist.videos) ? playlist.videos : []; return <PlaylistVideoList title={playlist.title} subtitle={`${playlist.author || 'Playlist'} · ${playlist.videoCount ?? videos.length} videos`} videos={videos} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} saveAll={() => update(state => ({ ...state, queue: [...videos, ...state.queue.filter(queued => !videos.some(video => video.videoId === queued.videoId))] }))} />; }
  if (base === 'subscriptions') { const result = data as { status: string; videos: Video[]; ready_count?: number; pending_count?: number } | null; const videos = matchingVideos(result?.videos || [], feedQuery); const page = feedPage(videos, feedPageIndex); const indicator = feedRefreshIndicator(feedRefreshing); return <><div className="heading"><h1>Feed {indicator ? <span className="feed-spinner" role="status" aria-label={indicator.label}>◌</span> : null}</h1></div>{!store.subscriptions.length ? <p className="empty">Subscribe from a channel page or import Google Takeout subscriptions in Settings.</p> : <><div className="channels-search video-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.4" /><path d="m16 16 4.5 4.5" /></svg><input type="search" value={feedQuery} onChange={event => { setFeedQuery(event.currentTarget.value); setFeedPageIndex(0); }} placeholder="Search feed" aria-label="Search feed videos" /></div>{feedError ? <p className="notice">{feedError}</p> : null}{result?.status === 'fetching' && !store.feedCache.videos.length ? <p className="notice">Preparing feeds for {result.pending_count || 0} imported channels.</p> : null}{videos.length ? <><VideoCards videos={page.videos} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markVideoWatched} addToPlaylist={addToPlaylist} />{page.pages > 1 ? <div className="actions"><button className="secondary" disabled={page.page === 0} onClick={() => setFeedPageIndex(current => Math.max(0, current - 1))}>Previous</button><span className="subtle">Page {page.page + 1} of {page.pages}</span><button className="secondary" disabled={page.page + 1 === page.pages} onClick={() => setFeedPageIndex(current => current + 1)}>Next</button></div> : null}</> : <p className="empty">{feedQuery ? 'No feed videos match that search.' : 'No videos are ready yet. Imported feeds are fetched in the background.'}</p>}</>}</>; }
  return <p className="empty">Choose a section from the sidebar.</p>;
}

function Player({ video, store, update, navigate, save, queue, notify, markWatched, addToPlaylist }: { video: any; store: Store; update: (f: (s: Store) => Store) => void; navigate: (r: string) => void; save: (v: Video) => void; queue: (v: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void }) {
  const [selected, setSelected] = useState(store.settings.quality);
  const playerRef = useRef<HTMLVideoElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const formats = playableVideoFormats(video);
  const selectedItag = selected === 'auto' || formats.some((format: { itag: string }) => format.itag === selected) ? selected : 'auto';
  const supportsNativeHls = document.createElement('video').canPlayType('application/vnd.apple.mpegurl') !== '';
  const source = choosePlaybackSource(video, supportsNativeHls, selectedItag);
  const audioSource = chooseAudioSource(video, selectedItag);
  const useHlsJs = requiresHlsJs(video, source, supportsNativeHls);
  const url = proxyPlaybackUrl(source);
  const audioUrl = proxyPlaybackUrl(audioSource);
  const upstreamUrl = upstreamShareUrl(video);
  const share = async () => {
    if (!upstreamUrl) return notify('The upstream source link is unavailable for this video.');
    try {
      if (navigator.share) await navigator.share({ title: video.title, url: upstreamUrl });
      else if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(upstreamUrl); notify('Upstream link copied to clipboard.'); }
      else {
        const field = document.createElement('textarea'); field.value = upstreamUrl; field.style.position = 'fixed'; field.style.opacity = '0'; document.body.append(field); field.select(); const copied = document.execCommand('copy'); field.remove(); if (!copied) throw new Error('Clipboard unavailable'); notify('Upstream link copied to clipboard.');
      }
    } catch (error) { if ((error as Error).name !== 'AbortError') notify('Unable to share this link.'); }
  };
  useEffect(() => {
    if (!useHlsJs || !url || !playerRef.current || !Hls.isSupported()) return;
    const hls = new Hls();
    hls.loadSource(url);
    hls.attachMedia(playerRef.current);
    return () => hls.destroy();
  }, [url, useHlsJs]);
  const existing = store.history.find(entry => entry.videoId === video.videoId);
  const record: Video = { ...video, resume: existing?.resume, paused: existing?.paused };
  useEffect(() => update(state => ({ ...state, history: updatePlayback(state.history, record, record.resume || 0, record.paused === true) })), [video.videoId]);
  return <div className={playerLayoutClass}><section><video ref={playerRef} className="player" controls autoPlay={shouldAutoplay(record, store.settings.autoplay)} playsInline src={useHlsJs ? undefined : url} onLoadedMetadata={event => { const resume = resumePosition(record); if (resume) { event.currentTarget.currentTime = resume; if (audioRef.current) audioRef.current.currentTime = resume; } }} onPlay={() => { if (audioRef.current) void audioRef.current.play().catch(() => undefined); update(state => ({ ...state, history: updatePlayback(state.history, record, playerRef.current?.currentTime || 0, false) })); }} onPause={() => { if (audioRef.current) audioRef.current.pause(); update(state => ({ ...state, history: updatePlayback(state.history, record, playerRef.current?.currentTime || 0, true) })); }} onSeeking={event => { if (audioRef.current) audioRef.current.currentTime = event.currentTarget.currentTime; }} onTimeUpdate={event => { const currentTime = event.currentTarget.currentTime; update(state => { const history = updatePlayback(state.history, record, currentTime, false); return { ...state, history: hasReachedWatchThreshold(record, currentTime) ? markHistoryWatched(history, record) : history }; }); }}><track kind="captions" /></video>{audioUrl ? <audio ref={audioRef} src={audioUrl} preload="auto" /> : null}<div className="heading"><div><h1 className="player-title">{video.title}</h1><button className="channel" onClick={() => navigate(`channel/${encodeURIComponent(video.authorId)}`)}>{video.author}</button></div><label className="quality-selector">Resolution &amp; frame rate<select className="filter" aria-label="Resolution and frame rate" value={selectedItag} onChange={event => { const quality = event.currentTarget.value; setSelected(quality); update(state => ({ ...state, settings: { ...state.settings, quality } })); }}><option value="auto">Auto</option>{formats.map((format: any) => <option value={format.itag} key={format.itag}>{streamQualityLabel(format)}</option>)}</select></label></div><div className="actions player-actions"><VideoActions video={record} saved={store.queue.some(bookmark => bookmark.videoId === record.videoId)} save={save} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} more={false} />{source && <a className="secondary" href={downloadUrl(source, video.title)} download>Download MP4</a>}</div><p className="description">{video.description || 'No description available.'}</p></section><aside><h2>Up next</h2>{video.recommendedVideos?.length ? <VideoCards videos={video.recommendedVideos} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} /> : <p className="subtle">Recommendations are unavailable for this extraction.</p>}</aside></div>;
}

function ChannelPage({ info, videos, fetching, store, update, navigate, save, queue, controls, notify, markWatched, addToPlaylist }: { info: Channel; videos: Video[]; fetching: boolean; store: Store; update: (f: (s: Store) => Store) => void; navigate: (r: string) => void; save: (v: Video) => void; queue: (v: Video) => void; controls: ParentalControls; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void }) { const subscribed = store.subscriptions.some(s => s.authorId === info.authorId); const avatar = channelAvatar(info); return <><section className="channel-head"><span className="avatar">{avatar.image ? <img src={avatar.image} alt="" /> : <span aria-label={`No profile image for ${info.author}`}>{avatar.initial}</span>}</span><div><h1 className={channelTitleClass}>{info.author}</h1><p className="meta">{info.subCount ? `${nfmt(info.subCount)} subscribers` : ''}</p><div className="actions">{!controls.enabled || !controls.disableSubscriptions ? <button className="primary" onClick={() => update(s => ({ ...s, subscriptions: subscribed ? s.subscriptions.filter(x => x.authorId !== info.authorId) : [info, ...s.subscriptions] }))}>{subscribed ? 'Subscribed' : 'Subscribe'}</button> : <p className="subtle">Subscription changes are disabled by parental controls.</p>}<button className="secondary" type="button" onClick={() => shareChannel(info, notify)}>Share</button></div></div></section>{fetching && <p className="notice">Preparing this channel’s feed…</p>}<VideoCards videos={videos} bookmarks={store.queue} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} /></>; }
function Library({ title, videos, bookmarks, navigate, save, queue, notify, markWatched, addToPlaylist, clear }: { title: string; videos: Video[]; bookmarks: Video[]; navigate: (r: string) => void; save: (v: Video) => void; queue: (v: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void; clear: () => void }) { const [query, setQuery] = useState(''); const filtered = matchingVideos(videos, query); const history = title === 'Watch history'; return <><div className="heading"><h1>{title}</h1><button className="secondary" onClick={clear}>Clear</button></div>{history && <div className="channels-search video-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.4" /><path d="m16 16 4.5 4.5" /></svg><input type="search" value={query} onChange={event => setQuery(event.currentTarget.value)} placeholder="Search history" aria-label="Search history videos" /></div>}{filtered.length ? <VideoCards videos={filtered} bookmarks={bookmarks} navigate={navigate} save={save} queue={queue} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} /> : <p className="empty">{query ? 'No history videos match that search.' : 'Nothing here yet.'}</p>}</>; }
function Playlists({ store, update, navigate }: { store: Store; update: (f: (s: Store) => Store) => void; navigate: (r: string) => void }) {
  const [name, setName] = useState('');
  const create = (event: FormEvent) => {
    event.preventDefault();
    if (!name.trim()) return;
    update(s => ({ ...s, playlists: [...s.playlists, createEmptyLocalPlaylist(name.trim())] }));
    setName('');
  };
  return <><div className="heading"><h1>Local playlists</h1></div><form className="search" onSubmit={create}><input value={name} onChange={e => setName(e.target.value)} placeholder="New playlist name" /><button>Create</button></form><div className="section">{store.playlists.length ? store.playlists.map(p => <div className="row" key={p.id}><button className="card-title" onClick={() => navigate(`local-playlist/${p.id}`)}>{p.name}</button><span className="meta">{p.videos.length} videos</span><button className="secondary" onClick={() => update(s => ({ ...s, playlists: s.playlists.filter(x => x.id !== p.id) }))}>Delete</button></div>) : <p className="empty">Create a local playlist, then use the video menu to add videos.</p>}</div></>;
}
function Queue({ store, update, navigate, save, notify, markWatched, addToPlaylist }: { store: Store; update: (f: (s: Store) => Store) => void; navigate: (r: string) => void; save: (v: Video) => void; notify: (message: string | null) => void; markWatched: (video: Video) => void; addToPlaylist: (video: Video) => void }) { return <><div className="heading"><h1>Save</h1><button className="secondary" onClick={() => update(s => ({ ...s, queue: [] }))}>Clear</button></div>{store.queue.length ? store.queue.map((v, index) => <div className="row" key={`${v.videoId}-${index}`}><img src={thumb(v)} /><button className="card-title" onClick={() => navigate(`watch/${v.videoId}`)}>{v.title}</button><VideoMenu video={v} notify={notify} markWatched={markWatched} addToPlaylist={addToPlaylist} /><button className="secondary" onClick={() => update(s => ({ ...s, queue: s.queue.filter((_, i) => i !== index) }))}>Remove</button></div>) : <p className="empty">Save videos from any card or player.</p>}</>; }
function Settings({ store, update, controls, onControls, session }: { store: Store; update: (f: (s: Store) => Store) => void; controls: ParentalControls; onControls: (controls: ParentalControls) => void; session: { remote: boolean; localUpstream: boolean; isAdmin: boolean; localAdmin: boolean; username: string } }) {
  const [instanceUrl, setInstanceUrl] = useState(store.settings.instanceUrl);
  const [pin, setPin] = useState(''); const [status, setStatus] = useState(''); const [error, setError] = useState('');
  const [activeServer, setActiveServer] = useState<{ instanceUrl: string; configured: boolean; healthy: boolean; using: 'local' | 'remote'; detail?: string } | null>(null);
  const [managedUsers, setManagedUsers] = useState<ManagedUser[]>([]); const [targetUser, setTargetUser] = useState(''); const [managedHistory, setManagedHistory] = useState<Video[]>([]); const [importKey, setImportKey] = useState(0);
  useEffect(() => { if (session.remote && session.isAdmin) fetch('/web-admin/users').then(r => r.ok ? r.json() : Promise.reject()).then(data => setManagedUsers(visibleManagedUsers(true, data.users || []))).catch(() => setManagedUsers([])); }, [session]);
  useEffect(() => { fetch('/config/health').then(async r => ({ status: r.status, ...(await r.json()) })).then(c => setActiveServer({ instanceUrl: c.instanceUrl || '', configured: !!c.configured, healthy: c.healthy, using: c.using, detail: c.detail })).catch(() => setActiveServer({ instanceUrl: '', configured: false, healthy: false, using: 'local', detail: 'Health check unavailable' })); }, []);
  const requirePin = async () => { if (!controls.enabled || session.isAdmin) return; const response = await fetch('/controls/verify', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ currentPin: pin }) }); if (!response.ok) throw new Error((await response.json()).detail || 'PIN required'); };
  const serverPayload = (instanceUrl: string) => ({ instanceUrl, currentPin: pin });
  const testServer = async (payload: ReturnType<typeof serverPayload>) => { const response = await fetch('/config/test', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error((await response.json()).detail || 'Server connection failed'); };
  const saveServer = async (event: FormEvent) => { event.preventDefault(); try { const normalized = validateServerConfiguration(instanceUrl); const payload = serverPayload(normalized); await saveAfterSuccessfulTest(() => testServer(payload), async () => { const response = await fetch('/config', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error((await response.json()).detail || 'Unable to save server configuration'); }); setActiveServer({ instanceUrl: normalized, configured: !!normalized, healthy: true, using: normalized ? 'remote' : 'local' }); update(s => ({ ...s, settings: { ...s.settings, instanceUrl: normalized } })); setStatus(normalized ? 'Remote Yattee Server saved. Reloading to sign in…' : 'Local-only mode saved. Reloading…'); setError(''); window.setTimeout(() => location.reload(), 0); } catch (e) { setStatus(''); setError(e instanceof Error ? e.message : 'Unable to save server'); } };
  const testConnection = async () => { try { const normalized = validateServerConfiguration(instanceUrl); await testServer(serverPayload(normalized)); setStatus(normalized ? 'Remote Yattee Server is online.' : 'Local-only proxy is online.'); setError(''); } catch (e) { setStatus(''); setError(e instanceof Error ? e.message : 'Unable to connect'); } };
  const removeRemote = async () => { if (!confirm('Remove the configured remote server? This disables multi-user mode. Existing remote user settings remain stored for a future reconfiguration.')) return; try { const response = await fetch('/config/remove', { method: 'POST' }); if (!response.ok) throw new Error((await response.json()).detail || 'Unable to remove remote server'); location.reload(); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to remove remote server'); } };
  const importSubscriptions = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { await requirePin(); const imported = file.name.toLowerCase().endsWith('.csv') ? parseTakeoutSubscriptions(await file.text()) : archiveSubscriptions(new Uint8Array(await file.arrayBuffer()), file.name); const response = await fetch('/subscriptions/import', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ channels: imported, currentPin: pin }) }); if (!response.ok) throw new Error((await response.json()).detail || 'Unable to import subscriptions'); const saved = await response.json(); update(s => ({ ...s, subscriptions: saved.subscriptions })); setStatus(`Imported ${imported.length} subscriptions.`); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to import subscriptions'); } finally { setImportKey(value => value + 1); } };
  const logout = async () => { const response = await fetch('/logout', { method: 'POST' }); if (response.ok) location.reload(); else setError('Unable to log out'); };
  const controlsUrl = targetUser ? `/controls?user=${encodeURIComponent(targetUser)}` : '/controls';
  const selectManagedUser = async (key: string) => { try { setTargetUser(key); setManagedHistory([]); const [controlsResponse, historyResponse] = await Promise.all([fetch(key ? `/controls?user=${encodeURIComponent(key)}` : '/controls'), key ? fetch(`/web-admin/history?user=${encodeURIComponent(key)}`) : Promise.resolve(null)]); if (!controlsResponse.ok) throw new Error('Unable to load user controls'); const saved = await controlsResponse.json(); onControls({ ...defaultParentalControls, ...saved.controls }); if (historyResponse?.ok) setManagedHistory((await historyResponse.json()).history || []); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to load user'); } };
  const saveControls = async () => { try { const response = await fetch(controlsUrl, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ controls: { ...controls, pin: controls.enabled ? undefined : pin, enabled: !controls.enabled }, currentPin: pin }) }); if (!response.ok) throw new Error((await response.json()).detail || 'Unable to update parental controls'); const saved = await response.json(); onControls({ ...defaultParentalControls, ...saved.controls }); setStatus(saved.controls.enabled ? 'Parental controls enabled.' : 'Parental controls disabled.'); setError(''); setPin(''); } catch (e) { setStatus(''); setError(e instanceof Error ? e.message : 'Unable to update parental controls'); } };
  const changeControl = async (field: keyof Omit<ParentalControls, 'enabled'>, value: boolean) => { try { await requirePin(); const response = await fetch(controlsUrl, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ controls: { ...controls, [field]: value }, currentPin: pin }) }); if (!response.ok) throw new Error((await response.json()).detail || 'PIN required'); const saved = await response.json(); onControls({ ...defaultParentalControls, ...saved.controls }); setStatus('Parental controls saved.'); setError(''); } catch (e) { setStatus(''); setError(e instanceof Error ? e.message : 'PIN required'); } };
  const changeLocal = async (fn: (s: Store) => Store) => { try { await requirePin(); update(fn); setStatus('Setting saved.'); setError(''); } catch (e) { setStatus(''); setError(e instanceof Error ? e.message : 'PIN required'); } };
  return <><h1>Settings</h1><div className="settings"><section className="dialog"><h2>Appearance</h2><p className="subtle">Themes and viewing preferences are persisted in this Yattee Web container’s filesystem.</p><label className="setting">Theme <select value={store.settings.theme} onChange={e => { const theme = e.currentTarget.value as Store['settings']['theme']; changeLocal(s => ({ ...s, settings: { ...s.settings, theme } })); }}><option value="default">Default dark</option><option value="light">Light</option><option value="nord">Nord</option><option value="catppuccin-mocha">Catppuccin Mocha</option><option value="solarized">Solarized</option><option value="dracula">Dracula</option></select></label></section>{!(controls.enabled && controls.disableSubscriptionImport) && <section className="dialog"><h2>Subscription importer</h2><p className="subtle">In Google Takeout, select <strong>YouTube and YouTube Music</strong> and ensure <strong>Subscriptions</strong> is checked. Then choose either its <code>subscriptions.csv</code>, the complete Takeout <code>.zip</code>, or its <code>.tar.gz</code> archive. Imported channels stay in this user’s Yattee Web profile.</p><label className="primary file-input">Choose Takeout file<input key={importKey} type="file" accept=".csv,text/csv,.zip,application/zip,.gz,application/gzip" onChange={importSubscriptions} /></label></section>}{(session.remote || session.localUpstream) && <section className="dialog"><h2>Account</h2><p className="subtle">Log out revokes this device’s Yattee Web session.</p><button className="danger" type="button" onClick={logout}>Log out</button></section>}<section className="dialog"><h2>Parental controls</h2><p className="subtle">Restrictions are saved on the server. When enabled, every Settings change requires the PIN.</p><input type="password" inputMode="numeric" value={pin} onChange={e => setPin(e.target.value)} placeholder={controls.enabled ? 'Enter PIN to change settings' : 'Set a 4–12 digit PIN'} autoComplete="off" />{!controls.enabled ? <button className="primary" type="button" onClick={saveControls}>Enable parental controls</button> : <><div className="restricted-options"><label className="setting">Disable Search <input type="checkbox" checked={controls.disableSearch} onChange={e => changeControl('disableSearch', e.target.checked)} /></label><label className="setting">Disable subscription changes <input type="checkbox" checked={controls.disableSubscriptions} onChange={e => changeControl('disableSubscriptions', e.target.checked)} /></label><label className="setting">Disable subscription import <input type="checkbox" checked={controls.disableSubscriptionImport} onChange={e => changeControl('disableSubscriptionImport', e.target.checked)} /></label><label className="setting">Disable saving, queues, and playlists <input type="checkbox" checked={controls.disablePlaylists} onChange={e => changeControl('disablePlaylists', e.target.checked)} /></label></div><button className="secondary" type="button" onClick={saveControls}>Disable parental controls</button></>}</section>{session.remote && session.isAdmin && <section className="dialog"><h2>Remote user management</h2><p className="subtle">Only accounts that have successfully logged into Yattee Web are listed here.</p><label className="setting">Manage user <select value={targetUser} onChange={e => selectManagedUser(e.target.value)}><option value="">{session.username || 'My profile'}</option>{managedUsers.map(user => <option key={user.id} value={user.id}>{user.username}</option>)}</select></label>{targetUser && <><h3>Watch history</h3>{managedHistory.length ? <ul>{managedHistory.slice(0, 30).map(video => <li key={video.videoId}>{video.title}</li>)}</ul> : <p className="subtle">No saved history.</p>}</>}<a className="primary" href="/admin">Manage Yattee Server options</a></section>}{(session.localAdmin || (session.remote && session.isAdmin)) && <form className="dialog" onSubmit={saveServer}><h2>Yattee Server</h2><p className="notice">{activeServer?.healthy && activeServer.using === 'remote' ? <>Active remote server: <strong>{activeServer.instanceUrl}</strong></> : activeServer?.configured && !activeServer.healthy ? <>Configured remote server failed its health check ({activeServer.detail || 'unavailable'}). <strong>Using the local proxy instead.</strong></> : 'Active server: this site’s local Yattee proxy.'}</p><p className="subtle">Leave the URL blank for single-user local-only mode. A configured remote enables multi-user mode: your browser will securely prompt for that remote server’s HTTP Basic credentials and Yattee Web never stores them.</p><input value={instanceUrl} onChange={e => setInstanceUrl(e.target.value)} placeholder="https://yattee.example.net" inputMode="url" /><div className="dialog-actions"><button className="secondary" type="button" onClick={testConnection}>Test server connection</button><button className="primary">Save server</button></div>{session.localAdmin && activeServer?.configured && <button className="danger" type="button" onClick={removeRemote}>Remove remote server</button>}</form>}{error && <p className="error">{error}</p>}{status && <p className="notice">{status}</p>}<label className="setting">Autoplay <input type="checkbox" checked={store.settings.autoplay} onChange={e => changeLocal(s => ({ ...s, settings: { ...s.settings, autoplay: e.target.checked } }))} /></label><label className="setting">Default speed <select className="filter" value={store.settings.speed} onChange={e => changeLocal(s => ({ ...s, settings: { ...s.settings, speed: +e.target.value } }))}>{[0.5,0.75,1,1.25,1.5,2].map(x => <option key={x}>{x}</option>)}</select></label></div></>;
}

createRoot(document.getElementById('root')!).render(<App />);
if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => undefined));
